package com.genc.ctds.samplelog.model;

import jakarta.persistence.*;

import java.time.LocalDate;

@Entity
@Table(name = "sample_log")
public class SampleLog {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private int sampleId;

    private int subjectId;

    private String sampleType;

    private LocalDate collectionDate;

    private LocalDate transitDate;

    private LocalDate analyzedDate;

    private LocalDate destroyedDate;

    private String collectedBy;

    private String labResult;

//@Enumerated(EnumType.STRING) tells JPA to store the enum value sampleStatus in the database as text like COLLECTED or ANALYZED instead of numbers.
    @Enumerated(EnumType.STRING)
    private SampleStatus sampleStatus;

    public SampleLog() {
        this.sampleStatus = SampleStatus.COLLECTED;
    }

    // Getters and setters
    public int getSampleId() { return sampleId; }
    public void setSampleId(int sampleId) { this.sampleId = sampleId; }

    public int getSubjectId() { return subjectId; }
    public void setSubjectId(int subjectId) { this.subjectId = subjectId; }

    public String getSampleType() { return sampleType; }
    public void setSampleType(String sampleType) { this.sampleType = sampleType; }

    public LocalDate getCollectionDate() { return collectionDate; }
    public void setCollectionDate(LocalDate collectionDate) { this.collectionDate = collectionDate; }

    public LocalDate getTransitDate() { return transitDate; }
    public void setTransitDate(LocalDate transitDate) { this.transitDate = transitDate; }

    public LocalDate getAnalyzedDate() { return analyzedDate; }
    public void setAnalyzedDate(LocalDate analyzedDate) { this.analyzedDate = analyzedDate; }

    public LocalDate getDestroyedDate() { return destroyedDate; }
    public void setDestroyedDate(LocalDate destroyedDate) { this.destroyedDate = destroyedDate; }

    public String getCollectedBy() { return collectedBy; }
    public void setCollectedBy(String collectedBy) { this.collectedBy = collectedBy; }

    public String getLabResult() { return labResult; }
    public void setLabResult(String labResult) { this.labResult = labResult; }

    public SampleStatus getSampleStatus() { return sampleStatus; }
    public void setSampleStatus(SampleStatus sampleStatus) { this.sampleStatus = sampleStatus; }

    public enum SampleStatus {
        COLLECTED("Collected"),
        IN_TRANSIT("In Transit"),
        ANALYZED("Analyzed"),
        DESTROYED("Destroyed");

        private final String displayName;

        SampleStatus(String displayName) {
            this.displayName = displayName;
        }

        public String getDisplayName() {
            return displayName;
        }
    }


}

